sys_variable_value.value:
(function execute(inputs, outputs) {


var taskUtils = new TaskUtils();
    var task = taskUtils.getTaskDetails(inputs.taskid);

    if (task) {
        outputs.name = task.name;
        outputs.due_date = task.due_date;
        outputs.state = task.state;
        outputs.assigned_to = task.assigned_to;
    } else {
        outputs.name = '';
        outputs.due_date = '';
        outputs.state = '';
        outputs.assigned_to = '';
    }

})(inputs, outputs);

